B.au5=new A.p("Can I have some water, please?","Biraz su alabilir miyim, l\xfctfen?","water say\u0131lamaz, some ile gelir",null)
B.aBV=new A.p("She has long brown hair.","Uzun kahverengi sa\xe7\u0131 var.","hair \xe7o\u011ful yap\u0131lmaz",null)
