B.aP2=new A.O("Does she likes coffee?","Does she like coffee?","\xdc\xe7\xfcnc\xfc tekil -s eki zaten does'un i\xe7indedir, bu y\xfczden ana fiil yal\u0131n kal\u0131r.",null)
B.aRd=new A.O("What means this word?","What does this word mean?","Ana fiilli soruda does eklenir ve \xf6zne ana fiilden \xf6nce gelir; T\xfcrk\xe7edeki 'Ne demek bu kelime' s\u0131ras\u0131 birebir \xe7evrilemez.",null)
