B.aur=new A.p("The second option is much more practical.","\u0130kinci se\xe7enek \xe7ok daha pratik.","much fark\u0131n b\xfcy\xfckl\xfc\u011f\xfcn\xfc verir",null)
B.au6=new A.p("It's not as far as I expected.","Sand\u0131\u011f\u0131m kadar uzak de\u011filmi\u015f.","not as ... as beklentiyi d\xfczeltir",null)
B.aux=new A.p("Your plan's better, honestly.","A\xe7\u0131k\xe7as\u0131 senin plan\u0131n daha iyi.","good-better d\xfczensiz kar\u015f\u0131la\u015ft\u0131rma",null)
B.aBX=new A.p("The more I use it, the more I like it.","Kulland\u0131k\xe7a daha \xe7ok seviyorum.","the more ... the more birlikte de\u011fi\u015fim",null)
B.aGu=new A.p("This bag's a bit heavier, but it's stronger.","Bu \xe7anta biraz daha a\u011f\u0131r ama daha sa\u011flam.","a bit k\xfc\xe7\xfck fark\u0131 anlat\u0131r",null)
B.aD3=new A.p("It's too expensive for what it is.","Sundu\u011fu \u015feye g\xf6re fazla pahal\u0131.","too olumsuz yarg\u0131 ta\u015f\u0131r",null)
B.azz=new A.p("I'd rather take the earlier train.","Daha erken treni tercih ederim.","I'd rather se\xe7im bildirir",null)
B.bgS=s([B.aAz,B.aur,B.au6,B.aux,B.aBX,B.aGu,B.aD3,B.azz],t.W)
