B.axO=new A.p("I'd love to grab a coffee sometime \u2014 are you around this weekend?","Bir ara kahve i\xe7mek isterim; bu hafta sonu m\xfcsait misin?","Davet: eylem + zaman aral\u0131\u011f\u0131, ikisi birlikte",null)
B.avk=new A.p("No pressure at all, but I'd really like to see you again.","Hi\xe7 bask\u0131 yapmak istemem ama seni yine g\xf6rmek isterim.","no pressure: ka\xe7\u0131\u015f pay\u0131 b\u0131rakan zorunlu ek",null)
B.aHQ=new A.p("Should I get your number, or is Instagram easier?","Numaran\u0131 alsam m\u0131, yoksa Instagram daha kolay m\u0131?","Kanal\u0131 se\xe7enekli sormak bask\u0131y\u0131 d\xfc\u015f\xfcr\xfcr",null)
B.aIy=new A.p("Are you seeing anyone at the moment?","\u015eu s\u0131ralar biriyle g\xf6r\xfc\u015f\xfcyor musun?","Do\u011fal ama zaman\u0131 olan bir soru, a\xe7\u0131l\u0131\u015fta de\u011fil",null)
B.aEK=new A.p("I'd love to, but I've got family over this weekend.","\xc7ok isterim ama bu hafta sonu ailem burada.","Kap\u0131y\u0131 aral\u0131k b\u0131rakan yumu\u015fak ret",null)
B.aCG=new A.p("That's really kind of you, but I'm not looking for anything right now.","Bunu s\xf6ylemen \xe7ok ho\u015f ama \u015fu s\u0131ralar bir \u015fey aray\u0131\u015f\u0131nda de\u011filim.","Net ama k\u0131rmayan ret: olumlu c\xfcmle + s\u0131n\u0131r",null)
B.axw=new A.p("No worries at all \u2014 it was good to meet you.","Hi\xe7 sorun de\u011fil; tan\u0131\u015ft\u0131\u011f\u0131m\u0131za sevindim.","Reddi kar\u015f\u0131laman\u0131n tek do\u011fru hamlesi",null)
B.bA6=s([B.aue,B.axO,B.avk,B.aHQ,B.aIy,B.aEK,B.aCG,B.axw],t.W)
B.aP9=new A.O("Do you want to be my girlfriend?","I've really enjoyed this \u2014 would you want to do it again sometime?","\u0130ngilizce fl\xf6rt dili a\u015famal\u0131d\u0131r; ili\u015fki tan\u0131m\u0131 ilk davette de\u011fil birka\xe7 g\xf6r\xfc\u015fme sonra konu\u015fulur ve erken sorulmas\u0131 kar\u015f\u0131 taraf\u0131 k\xf6\u015feye s\u0131k\u0131\u015ft\u0131r\u0131r.",null)
B.aPL=new A.O("Why not? Just tell me the reason.","No worries at all \u2014 have a good night.","Reddin sebebini sormak ya da \u0131srar etmek sosyal kodda s\u0131n\u0131r ihlalidir; gelen ret a\xe7\u0131klama gerektirmeden kabul edilir.",null)
