B.avP=new A.p("I'm gonna head out \u2014 I've got an early start tomorrow.","Ben \xe7\u0131k\u0131yorum, yar\u0131n sabah erken kalkaca\u011f\u0131m.","head out: kalkmak, ayr\u0131lmak; sebeple birlikte kibar",null)
