B.caa={altglyph:0,altglyphdef:1,altglyphitem:2,animatecolor:3,animatemotion:4,animatetransform:5,clippath:6,feblend:7,fecolormatrix:8,fecomponenttransfer:9,fecomposite:10,feconvolvematrix:11,fediffuselighting:12,fedisplacementmap:13,fedistantlight:14,feflood:15,fefunca:16,fefuncb:17,fefuncg:18,fefuncr:19,fegaussianblur:20,feimage:21,femerge:22,femergenode:23,femorphology:24,feoffset:25,fepointlight:26,fespecularlighting:27,fespotlight:28,fetile:29,feturbulence:30,foreignobject:31,glyphref:32,lineargradient:33,radialgradient:34,textpath:35}
